Q: How can a macro access a different structure member based on a parameter passed? A: <p>You can have conditionals in the preprocessor by using concatenation to produce macro names:</p>
<pre><code>struct s1 {
    int x;
};

struct s2 {
    int y;
};

#define MY_MACRO(ID, TYPE) do {  \
    TYPE new;                    \
    CAT(FOO_, ID)                \
} while(0);

#define FOO_1 new.x = 10;
#define FOO_2 new.y = 20;

#define CAT(x, y) CAT_(x, y)
#define CAT_(x, y) x##y

int main()
{
    MY_MACRO(1, struct s1);
    MY_MACRO(2, struct s2);

    return 0;
}
</code></pre>
